namespace QuantForge.Core;
public sealed record AndroidNativeValidationStatus(string AppVersion,string BuildCode,bool SourceValidated,bool ApkBuilt,bool ApkMatchedExactSource,bool DeviceAccepted,string Status,bool LiveTradingEnabled);
public static class AndroidNativeValidationStatusRules{public static AndroidNativeValidationStatus Create(string appVersion,string buildCode,ReleaseValidationMatrix matrix){if(string.IsNullOrWhiteSpace(appVersion)||string.IsNullOrWhiteSpace(buildCode))throw new InvalidOperationException("Android validation identity is required.");var status=matrix.DeviceAccepted?"Device accepted":matrix.NativeBuildValidated?"APK built; device acceptance pending":matrix.SourceValidated?"Source validated; APK build pending":"Source validation pending";return new(appVersion,buildCode,matrix.SourceValidated,matrix.NativeBuildValidated,matrix.NativeBuildValidated,matrix.DeviceAccepted,status,false);}}
